"use strict";

/**
 * Single source of truth for all breeds.
 * Add a new breed: just push another object - rendering, filtering, sorting,
 * the quiz and the comparison view all work off this list.
 *
 * Default order: Hebrew alphabet.
 *
 * Fields:
 *   key                – unique English id (used for URL + localStorage)
 *   nameHe / nameEn    – display name per language
 *   apiName            – breed name on dog.ceo (e.g. "retriever/golden")
 *   size               – Hebrew label ("קטן" | "בינוני" | "גדול")
 *   sizeRank           – 1=small, 2=medium, 3=large
 *   energy             – 1=low … 4=very high
 *   shedding           – 1=low, 2=medium, 3=high
 *   experience         – 1=beginner-friendly … 3=requires experienced owner
 *   lifespan           – average years
 *   description / descriptionEn – short description per language
 *   energyLabel / energyLabelEn – text label for energy
 *   lifespanLabel / lifespanLabelEn – text label for lifespan range
 *   sheddingLabel / sheddingLabelEn – text label for shedding
 *   character / characterEn       – character traits
 *   suitableFor / suitableForEn   – good fit for…
 *   origin / originEn             – country of origin
 *   weight / weightEn             – weight range
 *   exerciseHours      – recommended hours per day
 *   trainingDifficulty – 1=very easy … 5=very hard
 *   goodWithCats       – gets along with cats
 *   goodWithKids       – good with kids
 */
