/**
 * Heuristic price range when a breed isn't in BREED_PRICES_USD.
 * Larger / harder-to-handle dogs tend to cost more.
 */
function _defaultPriceFor(b) {
  const sizeBase = { 1: [800, 2000], 2: [1000, 2500], 3: [1200, 3000] };
  let [lo, hi] = sizeBase[b.sizeRank] || [800, 2500];
  if (b.experience >= 3) { lo = Math.round(lo * 1.3); hi = Math.round(hi * 1.3); }
  // Round to a nice $50 step so labels read cleanly.
  lo = Math.round(lo / 50) * 50;
  hi = Math.round(hi / 50) * 50;
  return [lo, hi];
}

// Rough USD → ILS conversion (shekels). Update if rates shift dramatically.
const _USD_TO_ILS = 3.7;
function _formatRange(min, max, sign) {
  const fmt = (n) => n.toLocaleString("en-US");
  return `${sign}${fmt(min)}–${fmt(max)}`;
}

// Enrich every breed with priceMin/priceMax (USD numeric) plus localized
// display labels. Keeping this here means filtering, sorting, and the UI
// all read consistent data without any extra plumbing.
BREEDS.forEach((b) => {
  const [usdMin, usdMax] = BREED_PRICES_USD[b.key] || _defaultPriceFor(b);
  b.priceMin = usdMin;
  b.priceMax = usdMax;
  const ilsMin = Math.round((usdMin * _USD_TO_ILS) / 100) * 100;
  const ilsMax = Math.round((usdMax * _USD_TO_ILS) / 100) * 100;
  b.priceLabel = _formatRange(ilsMin, ilsMax, "₪");
  b.priceLabelEn = _formatRange(usdMin, usdMax, "$");
});

if (typeof module !== "undefined" && module.exports) {
  module.exports = { BREEDS };
}
